pub(crate) fn table_for_host(host: &str) -> &'static [AaCodons] {
    match host {
        "e_coli" | "ecoli" | "e_coli_k12" | "e_coli_b" | "cell_free" | "other_bsl1"
        | "other" | "none" => ECOLI_K12_TABLE,
        "yeast" | "s_cerevisiae" => YEAST_TABLE,
        "human" | "h_sapiens" => HUMAN_TABLE,
        _ => ECOLI_K12_TABLE,
    }
}
